			digest: hex(digest),
			exactCanonicalPreimageBytes: Uint8Array.from(exactCanonicalPreimageBytes),
			ok: true as const,
			preparation,
			signingRequest: mintCreatorIssuanceRetirementSigningRequest(digest),
		});
